const PRODS=[{k:'SPX',n:'SPX (S&P 500 index option)',m:100,set:'Cash-settled, European'},{k:'XSP',n:'XSP (Mini-SPX, 1/10 the size of SPX)',m:100,set:'Cash-settled, European'},{k:'ES',n:'Option on E-mini S&P 500 futures (ES)',m:50,set:'Exercises into a futures contract (some short-dated series are cash-settled)'},{k:'MES',n:'Option on Micro E-mini S&P 500 futures (MES)',m:5,set:'Exercises into a futures contract (check specs)'},{k:'NQ',n:'Option on E-mini Nasdaq-100 futures (NQ)',m:20,set:'Exercises into a futures contract (check specs)'},{k:'MNQ',n:'Option on Micro E-mini Nasdaq-100 futures (MNQ)',m:2,set:'Exercises into a futures contract (check specs)'}];
LS.push({id:'futures',emoji:'🛢️',title:'Index & futures options',sub:'SPX, XSP, ES/MES • cash settlement',
scenes:[
{t:'Options aren\'t only on stocks. <b>Index options</b> like <b>SPX</b> are on the S&P 500 index itself. There are no shares to deliver, so they\'re <b>cash-settled</b>: if your option ends ITM, you get the ITM amount × <b>$100</b> in cash.',
 a:()=>svg(box(40,90,200,90,'#a78bfa','SPX','#0b1020',40)+arrow(250,135,350,135,'#facc15',.5)+`<g class="popin" ${D(1)}><text x="450" y="150" font-size="70" text-anchor="middle">💵</text></g>`+T(300,240,'No shares change hands, just cash','#e8ecf5',17,'popin',1.3))},
{t:'<i>Made-up example:</i> you own an <b>SPX 5,000 call</b>, and SPX settles at <b>5,030</b>. ITM amount = 30 points × $100 = <b>$3,000</b> cash. If you paid 20 points ($2,000), your profit is <b>$1,000</b>. <b>XSP</b> is <b>1/10 the size</b> of SPX, which is friendlier for small accounts.',
 a:()=>svg(T(300,60,'5,030 − 5,000 = 30 points','#facc15',24,'popin')+T(300,120,'30 × $100 = $3,000','#4ade80',28,'popin',.6)+T(300,180,'− $2,000 paid = $1,000 profit','#4ade80',22,'popin',1.2)+T(300,250,'XSP: same idea at 1/10 the size','#a78bfa',18,'popin',1.8))},
{t:'<b>Options on futures</b> (traded at CME) control <b>one futures contract</b>. Each point of option price is worth the futures multiplier: <b>ES $50</b>, <b>MES $5</b>, <b>NQ $20</b>, <b>MNQ $2</b>. So an MES option priced at 10 points costs 10 × $5 = <b>$50</b>.',
 a:()=>svg([['ES','$50 / pt','#60a5fa'],['MES','$5 / pt','#4ade80'],['NQ','$20 / pt','#f472b6'],['MNQ','$2 / pt','#facc15']].map(([a,b,c],i)=>`<g class="popin" ${D(i*.3)}><rect x="${30+i*140}" y="80" width="120" height="120" rx="16" fill="${c}"/><text x="${90+i*140}" y="135" font-size="28" font-weight="800" fill="#0b1020" text-anchor="middle">${a}</text><text x="${90+i*140}" y="170" font-size="17" font-weight="700" fill="#0b1020" text-anchor="middle">${b}</text></g>`).join('')+T(300,250,'Option points × futures multiplier = dollars','#e8ecf5',16,'popin',1.4))},
{t:'Many futures options <b>exercise into a futures position</b> rather than cash. For example, a long call becomes a long futures contract. Some short-dated series are <b>cash-settled</b>. Always check the contract specs on <b>CME Group\'s</b> website.',
 a:()=>svg(`<text x="130" y="160" font-size="70" text-anchor="middle">📜</text>`+arrow(200,140,380,140,'#facc15',.4)+T(290,120,'exercise','#facc15',16,'popin',.4)+box(400,100,170,80,'#60a5fa','Futures position','#0b1020',17,1)+T(300,260,'Long call → long futures • Long put → short futures','#e8ecf5',15,'popin',1.4))},
{t:'🧑‍💻 <b>You trade futures with Apex.</b> Prop firms set their own rules about which products are allowed, so check Apex\'s <b>current</b> rules before assuming options are permitted. This app <b>never</b> connects to Apex, TradingView or Tradovate, and it never places orders. It\'s for learning only.',
 a:()=>svg(coach(110,120)+bubble(170,30,380,'Check your prop firm\'s rules first. This app is for learning only!',.4)+T(380,230,'🚫 No broker connection • No orders','#f87171',18,'popin',1))}],
take:['SPX and XSP: index options, <b>European-style, cash-settled</b>, $100 per point (XSP is 1/10 the size of SPX).','Futures options: one contract controls one futures contract. Points × multiplier (ES $50, MES $5, NQ $20, MNQ $2).','Many futures options exercise into futures, and some are cash-settled, so check CME specs.','Check your prop firm\'s (Apex\'s) current rules before trading any new product.'],
tryit:el=>{el.innerHTML=`<h3>🛢️ Settlement calculator</h3><select id="fp" class="inp">${PRODS.map((p,i)=>`<option value="${i}">${p.n}</option>`).join('')}</select>${seg('ft',[['c','Call'],['p','Put']],'c')}<div class="grid2"><label>Strike <input id="fk" type="number" class="inp" value="5000"></label><label>Final price / settlement <input id="fs" type="number" class="inp" value="5030"></label><label>Premium paid (points) <input id="fpr" type="number" class="inp" value="20" step="0.25"></label><label>Contracts <input id="fn" type="number" class="inp" value="1" min="1"></label></div><div id="fo" class="outbox"></div>${SIM}`;
 const f=()=>{const p=PRODS[val('fp')],c=segVal(el,'ft')==='c',K=val('fk'),S=val('fs'),pr=val('fpr'),n=Math.max(1,val('fn'));const itm=c?Math.max(S-K,0):Math.max(K-S,0),v=itm*p.m*n,cost=pr*p.m*n;
  $('#fo').innerHTML=`<p><b>${p.k}</b>: $${p.m} per point • ${p.set}</p><div class="big">ITM amount: <b>${itm.toFixed(2)} pts</b> × $${p.m} × ${n} = <b class="g">${money(v)}</b></div><div class="big">Cost: ${pr} pts × $${p.m} × ${n} = <b class="y">${money(cost)}</b></div><div class="big">Result at expiration: <b class="${v-cost>=0?'g':'r'}">${smoney(v-cost,2)}</b></div>${p.m!==100||['ES','MES','NQ','MNQ'].includes(p.k)?'<p class="mut">For futures options, exercising usually gives you a futures position worth about this amount, rather than cash. Check CME specs.</p>':''}`};
 bindSeg(el,f);onAll(el,f)},
quiz:[
{q:'An SPX call with a 5,000 strike settles at 5,020. What is its cash value?',o:[['$2,000'],['$20','Multiply the points by $100.'],['$200','Multiply the 20 points by $100, not $10.'],['$502,000','That\'s the full index value × 100, not the ITM amount.']],a:0,ex:'20 points × $100 = $2,000.'},
{q:'How much is one point of an MES (Micro E-mini S&P) option worth?',o:[['$5'],['$50','$50 is the E-mini (ES).'],['$100','$100 is the SPX/XSP multiplier.'],['$2','$2 is the MNQ multiplier.']],a:0,ex:'MES futures are $5 × the index, so each option point = $5.'},
{q:'"Cash-settled" means…',o:[['The ITM value is paid in cash, and no shares or futures are delivered'],['You must pay in cash only','It describes how the option settles, not how you pay.'],['The option can never lose money','Cash-settled options can still expire worthless.'],['It settles every day','Settlement happens at expiration.']],a:0,ex:'SPX and XSP pay the ITM amount × $100 in cash.'},
{q:'Before trading options on futures in a prop-firm account, you should…',o:[['Check the firm\'s current rules on allowed products'],['Assume everything is allowed','Prop firms limit products, so check first.'],['Use this app to place the order','This app never connects to brokers or places orders.'],['Ignore contract specs','Specs tell you the size, settlement and expiration.']],a:0,ex:'Rules change, and breaking them can fail an evaluation.'}]});
