LS.push({id:'risk',emoji:'🧯',title:'Risk management',sub:'Position sizing & beginner mistakes',
scenes:[
{t:'Rule #1: <b>only trade money you can afford to lose</b>. Many traders cap the risk on any one trade at a small slice of their account. <b>1–2%</b> is a common guideline, not a law. That way, a losing streak doesn\'t wipe you out.',
 a:()=>svg(`<g transform="translate(180,150)"><circle r="100" fill="#243056"/><path d="M0 0 L0 -100 A100 100 0 0 1 12.5 -99.2 Z" fill="#f87171" class="pop-slice"/></g>`+T(180,280,'Risk ~1–2% per trade','#f87171',17,'popin',.6)+T(430,110,'10 losses in a row','#e8ecf5',18,'popin',1)+T(430,145,'at 2% each ≈ −18%','#facc15',22,'popin',1.3)+T(430,190,'at 20% each ≈ −89%','#f87171',22,'popin',1.6))},
{t:'<b>Position sizing</b> <i>(made-up example)</i>: a $5,000 account × 2% = <b>$100</b> max risk. An option costing $0.80 ($80) that you\'re willing to lose completely → <b>1 contract</b>. A $2.50 option ($250) would be <b>too big</b> for that budget.',
 a:()=>svg(box(40,70,160,70,'#60a5fa','$5,000','#0b1020',24)+T(220,115,'×','#fff',30,'popin',.4)+box(240,70,100,70,'#facc15','2%','#0b1020',24,.6)+T(360,115,'=','#fff',30,'popin',1)+box(380,70,180,70,'#4ade80','$100 max risk','#0b1020',20,1.3)+T(300,200,'$80 option → 1 contract ✅','#4ade80',19,'popin',1.7)+T(300,240,'$250 option → too big ❌','#f87171',19,'popin',2))},
{t:'Have an <b>exit plan before you enter</b>: where will you take profit, and where will you cut the loss? Write it down. Decide your plan when you\'re calm, not in the middle of a fast market.',
 a:()=>svg(`<rect x="170" y="40" width="260" height="220" rx="16" fill="#fef3c7" class="popin"/>`+T(300,80,'MY PLAN','#0b1020',20,'popin',.3)+T(300,125,'✅ Take profit at +50%','#15803d',17,'popin',.7)+T(300,165,'🛑 Exit at −50%','#b91c1c',17,'popin',1.1)+T(300,205,'⏰ Out 1 week before exp.','#1d4ed8',17,'popin',1.5)+T(300,245,'(example only)','#64748b',13,'popin',1.7))},
{t:'<b>Common beginner mistakes</b> ❌: buying far-OTM "lottery tickets", ignoring <b>IV crush</b>, holding to expiration by accident, selling <b>naked</b> options, trading too big, trading options with <b>wide spreads</b>, revenge trading after a loss, and having no plan.',
 a:()=>svg(['Lottery-ticket OTM buys','Ignoring IV crush','Too big a position','Naked selling','Wide-spread, illiquid options','Revenge trading'].map((m,i)=>`<g class="slideL" ${D(i*.3)}><text x="70" y="${50+i*42}" font-size="24">❌</text><text x="110" y="${50+i*42}" font-size="18" font-weight="700" fill="#e8ecf5">${m}</text></g>`).join(''))},
{t:'<b>Practice first</b> 🧪. Paper trade or use this app\'s Practice Lab until the ideas feel natural. Keep a <b>trading journal</b> of every trade: why you entered, how you exited, and what you learned. And remember, trading stress is real. Take breaks.',
 a:()=>svg(coach(120,120)+bubble(180,40,360,'Practice, journal, repeat. Small and steady wins the race. 🐢',.4)+T(380,240,'📓 Journal every trade','#facc15',19,'popin',1))}],
take:['Only risk money you can afford to lose. Many traders risk ~1–2% per trade.','Size = max $ risk ÷ risk per contract.','Plan your profit target and exit before entering.','Avoid lottery tickets, IV crush traps, naked selling, oversizing and revenge trades.','Practice first and keep a journal.'],
tryit:el=>{el.innerHTML=`<h3>🧯 Position-size calculator</h3><div class="grid2"><label>Account size ($)<input id="ra" type="number" class="inp" value="5000"></label><label>Max risk per trade (%)<input id="rp" type="number" class="inp" value="2" step="0.5"></label><label>Option price (per share)<input id="ro" type="number" class="inp" value="0.80" step="0.05"></label><label>Exit if the option loses (%)<input id="rs" type="number" class="inp" value="100" step="5"></label></div><div id="ro2" class="outbox"></div>${SIM}`;
 onAll(el,()=>{const A=val('ra'),P=val('rp'),O=val('ro'),St=Math.min(100,Math.max(1,val('rs')));const budget=A*P/100,per=O*100*St/100,n=per>0?Math.floor(budget/per):0;
  $('#ro2').innerHTML=`<div class="big">Max risk: <b class="y">${money(budget)}</b></div><div class="big">Risk per contract: ${money(O*100)} × ${St}% = <b>${money(per)}</b></div><div class="big">Max contracts: <b class="${n>0?'g':'r'}">${n}</b></div>${n===0?'<p class="r">Even one contract risks more than your limit. Choose a cheaper option, a spread, or skip the trade.</p>':''}<p class="mut">A stop isn\'t guaranteed. Options can gap past it, so many beginners size as if the whole premium could be lost (100%).</p>`})},
quiz:[
{q:'Account $10,000, max risk 1% per trade. What is the max dollar risk?',o:[['$100'],['$1,000','That\'s 10%.'],['$10','That\'s 0.1%.'],['$1','That\'s 0.01%.']],a:0,ex:'$10,000 × 1% = $100.'},
{q:'Your max risk is $150. An option costs $0.70, and you size for a 100% loss. How many contracts can you buy?',o:[['2'],['3','3 × $70 = $210, which is over your limit.'],['21','You forgot the ×100 multiplier.'],['1','You can fit two ($140).']],a:0,ex:'Each contract risks $70, and $150 ÷ $70 = 2.14 → 2 contracts.'},
{q:'Which is a common beginner mistake?',o:[['Buying cheap far-OTM options as "lottery tickets"'],['Keeping a trading journal','That\'s a GOOD habit.'],['Setting an exit plan before entering','That\'s a GOOD habit.'],['Practicing with a simulator first','That\'s a GOOD habit.']],a:0,ex:'Far-OTM options are cheap because they usually expire worthless.'},
{q:'When should you decide your exit plan?',o:[['Before you enter the trade'],['After you\'re down 50%','By then emotions take over.'],['Never, just go with your gut','No plan usually means bigger losses.'],['Only if the trade is winning','Plan for both outcomes.']],a:0,ex:'A plan made calmly beats decisions made under stress.'}]});

